  @doc "Every theme, in the order the desktop app offers them; the first is the default."
  @spec themes() :: [
          %{id: theme(), name: String.t(), description: String.t(), reserved: String.t()}
        ]
  def themes, do: @themes

  @doc "A theme's roles: each one's token, dark and light values with their xterm-256 nearest, and its stand-in among the sixteen."
  @spec roles(theme()) :: %{role() => map()}
  def roles(theme \\ :afterglow), do: Map.fetch!(@roles, theme)

  @doc "The mask at a cut: `:large` is 16 cells wide, `:small` 10."
  @spec mask(:large | :small) :: mask()
  def mask(:large),
    do: [
      "...oooooooooo...",
      "..oooooooooooo..",
      ".oo.....fffffoo.",
      "oo......ffffffoo",
      "oo......ffffffoo",
      "oo......ffffffoo",
      "oo......ffffffoo",
      "oo..eee.fcccffoo",
      "oo......ffffffoo",
      "oo......ffffffoo",
      "oo......ffffffoo",
      "oo......ffffffoo",
      ".oo.....fffffoo.",
      ".oo.....fffffoo.",
      "..oo....ffffoo..",
      "...ooo..ffooo...",
      "....ooo.fooo....",
      ".....oooooo.....",
      ".......oo.......",
      "................"
    ]

  def mask(:small),
    do: [
      "..oooooo..",
